-- 执行 Operation 类型对象的指定方法。

local function execute(service, functionName)
	if not service then
		return
	end
	if not service[functionName] then
		return
	end
	if service.new then
		service[functionName](service)
	else
		service[functionName]()
	end
end

return function(serviceProvider: IServiceProvider, functionName: string?)
	local hostEnv: IHostingEnvironment = serviceProvider:GetService("IHostingEnvironment")
	local luaTypeProvider: ILuaTypeProvider = serviceProvider:GetService("ILuaTypeProvider")
	for k, v in luaTypeProvider.Types do
		if v.__IsOperation then
			local isMathContext = hostEnv:MatchContext(v.__Context)
			if isMathContext then
				local service = serviceProvider:GetService(k)
				execute(service, functionName)
			end
		end
	end
end
